/*=----------------------------------------------------------------------=*\
   Use :Return temperature reading as a float value in degrees C
       :
       :Returns : MX_FLOAT
\*=----------------------------------------------------------------------=*/
MX_FLOAT FCD_07c21_Grove_Humidity_SHT31__GetTemperatureReal()
{
  //Local variable definitions
  MX_UINT16 FCL_TEMP;
  MX_FLOAT FCR_RETVAL;


  FCD_07c21_Grove_Humidity_SHT31__GetData();

  FCR_RETVAL = flt_fromi(FCV_07c21_Grove_Humidity_SHT31__TEMP);
  FCR_RETVAL = flt_div(FCR_RETVAL, 65535.0);
  FCR_RETVAL = flt_mul(FCR_RETVAL, 175.0);
  FCR_RETVAL = flt_sub(FCR_RETVAL, 45.0);

  return (FCR_RETVAL);

}

