/*=----------------------------------------------------------------------=*\
   Use :Reads the raw temperature and humidity registers and stores the values locally.
       :Returns 1 if the data was sampled succesfully.
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCD_07c21_Grove_Humidity_SHT31__GetData()
{
  //Local variable definitions
  MX_UINT8 FCL_RET;
  MX_UINT8 FCL_RETRYCOUNT = (0xa);
  #define FCLsz_DATA 6
  MX_UINT8 FCL_DATA[FCLsz_DATA];
  MX_UINT8 FCR_RETVAL;


  FCR_RETVAL = 0;

  FCL_DATA[0] = 0x24;
  FCL_DATA[1] = 0x0B;

  FC_CAL_I2C_Transaction_Write_1(FCL_DATA, 6, 2);

  while (FCL_RETRYCOUNT > 0)
  {
    FCL_RET = FC_CAL_I2C_Transaction_Read_1(FCL_DATA, 6, 6);

    if (FCL_RET == 6)
    {    

      FCV_07c21_Grove_Humidity_SHT31__TEMP = (FCL_DATA[0] << 8) | FCL_DATA[1];
      FCV_07c21_Grove_Humidity_SHT31__HUM = (FCL_DATA[3] << 8) | FCL_DATA[4];

      FCR_RETVAL = 1;

      FCL_RETRYCOUNT = 0;

    } else {

      FCL_RETRYCOUNT = FCL_RETRYCOUNT - 1;

      FCI_DELAYBYTE_MS(10);

    }

  }

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_DATA
}

/*=----------------------------------------------------------------------=*\
   Use :Configures the I2C peripheral and puts the sensor into one shot mode ready to be sampled. Must be called before calling any of the other component macros.
       :Returns 1 if the sensor has been intialised correctly, else returns 0.
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCD_07c21_Grove_Humidity_SHT31__Initialise()
{
  //Local variable definitions
  #define FCLsz_DATA 2
  MX_UINT8 FCL_DATA[FCLsz_DATA];
  MX_UINT8 FCR_RETVAL;


  FCV_07c21_Grove_Humidity_SHT31__HUM = 0;
  FCV_07c21_Grove_Humidity_SHT31__TEMP = 0;

  FC_CAL_I2C_Transaction_Init_1(68);

  //Comment:
  //One Shot mode without clock stretching 

  FCL_DATA[0] = 0x30;
  FCL_DATA[1] = 0x41;

  FCR_RETVAL = FC_CAL_I2C_Transaction_Write_1(FCL_DATA, 2, 2);

  if (FCR_RETVAL == 2)
  {  

    FCR_RETVAL = 1;

  } else {

    FCR_RETVAL = 0;

  }

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_DATA
}


